DRUGTOK_CACHE_DIR = os.path.join(LOCAL_CACHE_ROOT, f"drugtok_cache_biosnap_{SAFE_SCENARIO_NAME}")

for d in [LOCAL_CACHE_ROOT, ESM_CACHE_DIR, DRUGTOK_CACHE_DIR]:
    os.makedirs(d, exist_ok=True)

